const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const entryModule = 'lib/client/chat_ui_app.js';

function toBundlePath(filename) {
  return filename.split(path.sep).join('/');
}

function moduleSource(filename) {
  return fs.readFileSync(path.join(root, filename), 'utf8');
}

function localRequireRequests(source) {
  const requests = [];
  const pattern = /require\(\s*['"](\.[^'"]*)['"]\s*\)/g;
  let match = pattern.exec(source);
  while (match) {
    requests.push(match[1]);
    match = pattern.exec(source);
  }
  return requests;
}

function resolveLocalRequest(fromModule, request) {
  const fromDir = path.dirname(fromModule);
  const candidate = toBundlePath(path.normalize(path.join(fromDir, request)));
  const filename = candidate.endsWith('.js') ? candidate : `${candidate}.js`;
  const absolute = path.join(root, filename);
  if (!fs.existsSync(absolute)) {
    throw new Error(`Cannot resolve ${request} from ${fromModule}`);
  }
  return filename;
}

function discoverClientModules(entry = entryModule) {
  const modules = [];
  const dependencyMap = {};
  const seen = new Set();

  function visit(filename) {
    if (seen.has(filename)) return;
    seen.add(filename);
    const source = moduleSource(filename);
    const deps = {};
    for (const request of localRequireRequests(source)) {
      const resolved = resolveLocalRequest(filename, request);
      deps[request] = resolved;
      visit(resolved);
    }
    dependencyMap[filename] = deps;
    modules.push(filename);
  }

  visit(entry);
  return { modules, dependencyMap };
}

function buildBundle(entry = entryModule) {
  const { modules, dependencyMap } = discoverClientModules(entry);
  const moduleEntries = modules.map((filename) => {
    const deps = dependencyMap[filename] || {};
    return `${JSON.stringify(filename)}: [function(require, module, exports) {\n`
    + `eval(${JSON.stringify(moduleSource(filename))} + "\\n//# sourceURL=${filename}");\n`
    + `}, ${JSON.stringify(deps)}]`;
  });

  return `/* Generated by scripts/build_client_bundle.js. Do not edit by hand. */\n`
  + `(function () {\n`
  + `  const modules = {\n    ${moduleEntries.join(',\n    ')}\n  };\n`
  + `  const cache = {};\n`
  + `  function requireModule(id) {\n`
  + `    if (cache[id]) return cache[id].exports;\n`
  + `    if (!modules[id]) throw new Error('Module not found: ' + id);\n`
  + `    const module = { exports: {} };\n`
  + `    cache[id] = module;\n`
  + `    const localRequire = (request) => {\n`
  + `      const mapped = modules[id][1][request];\n`
  + `      if (!mapped) throw new Error('Dependency not mapped: ' + request + ' from ' + id);\n`
  + `      return requireModule(mapped);\n`
  + `    };\n`
  + `    modules[id][0](localRequire, module, module.exports);\n`
  + `    return module.exports;\n`
  + `  }\n`
  + `  requireModule(${JSON.stringify(entry)});\n`
  + `})();\n`;
}

function writeBundle() {
  fs.writeFileSync(path.join(root, 'app.bundle.js'), buildBundle(), 'utf8');
  console.log('wrote app.bundle.js');
}

if (require.main === module) {
  writeBundle();
}

module.exports = {
  buildBundle,
  discoverClientModules,
  localRequireRequests,
  resolveLocalRequest,
  writeBundle,
};
